svg.script:
(() => {
  let frameId = 0;
  let startedAt = 0;
  const qaTimeParam = new URLSearchParams(location.search).get('qaTime');
  const fixedQaSeconds = qaTimeParam === null ? null : Number(qaTimeParam);

  function rotate(id, angle) {
    const element = document.getElementById(id);
    if (!element) return;
    const x = element.dataset.pivotX;
    const y = element.dataset.pivotY;
    element.setAttribute('transform', `rotate(${angle} ${x} ${y})`);
  }

  function moveRoot(x, y) {
    document.getElementById('rig-person')?.setAttribute('transform', `translate(${x} ${y})`);
  }

  function setLeftLegSpread(angle) {
    document.getElementById('rig-leg-left-spread')
      ?.setAttribute('transform', `rotate(${angle} 392 575)`);
  }

  function shoeAnkleFromContact(contactX, contactY, rootX, rootY, heelAngle = 0) {
    const radians = heelAngle * Math.PI / 180;
    const pivotOffset = heelAngle >= 0
      ? { x: 89, y: 48 }
      : { x: -36, y: 48 };
    const soleCentreOffset = { x: 50.5, y: 48 };
    const pivotAnchorX = contactX + pivotOffset.x - soleCentreOffset.x;
    const pivotAnchorY = contactY + pivotOffset.y - soleCentreOffset.y;
    const rotatedPivotX = pivotOffset.x * Math.cos(radians) - pivotOffset.y * Math.sin(radians);
    const rotatedPivotY = pivotOffset.x * Math.sin(radians) + pivotOffset.y * Math.cos(radians);
    return {
      x: pivotAnchorX - rootX - rotatedPivotX,
      y: pivotAnchorY - rootY - rotatedPivotY
    };
  }

  function solveLeg(contactX, contactY, rootX, rootY, hipShift = 0, heelAngle = 0) {
    const upperVector = { x: 16, y: 195 };
    const lowerVector = { x: -11, y: 200 };
    const upperLength = Math.hypot(upperVector.x, upperVector.y);
    const lowerLength = Math.hypot(lowerVector.x, lowerVector.y);
    const upperBase = Math.atan2(upperVector.y, upperVector.x);
    const lowerBase = Math.atan2(lowerVector.y, lowerVector.x);
    const ankle = shoeAnkleFromContact(contactX, contactY, rootX, rootY, heelAngle);
    const ankleX = ankle.x;
    const ankleY = ankle.y;
    const dx = ankleX - (392 + hipShift);
    const dy = ankleY - 575;
    const distanceSquared = dx * dx + dy * dy;
    const cosine = Math.max(-1, Math.min(1,
      (distanceSquared - upperLength * upperLength - lowerLength * lowerLength)
      / (2 * upperLength * lowerLength)
    ));
    const bend = Math.acos(cosine);
    const upperWorld = Math.atan2(dy, dx)
      - Math.atan2(lowerLength * Math.sin(bend), upperLength + lowerLength * Math.cos(bend));
    const toDegrees = 180 / Math.PI;
    const upper = (upperWorld - upperBase) * toDegrees;
    const lower = (bend + upperBase - lowerBase) * toDegrees;
    return { upper, lower, foot: heelAngle - (upper + lower) };
  }

  function plantedRootY(contactX, contactY, rootX, hipShift = 0, heelAngle = 0, kneeBendDegrees = 4) {
    const upperVector = { x: 16, y: 195 };
    const lowerVector = { x: -11, y: 200 };
    const upperLength = Math.hypot(upperVector.x, upperVector.y);
    const lowerLength = Math.hypot(lowerVector.x, lowerVector.y);
    const upperBase = Math.atan2(upperVector.y, upperVector.x);
    const lowerBase = Math.atan2(lowerVector.y, lowerVector.x);
    const plantedKneeBend = kneeBendDegrees * Math.PI / 180;
    const bend = plantedKneeBend - upperBase + lowerBase;
    const reach = Math.sqrt(
      upperLength * upperLength + lowerLength * lowerLength
      + 2 * upperLength * lowerLength * Math.cos(bend)
    );
    const ankle = shoeAnkleFromContact(contactX, contactY, rootX, 0, heelAngle);
    const ankleX = ankle.x;
    const horizontal = ankleX - (392 + hipShift);
    const vertical = Math.sqrt(Math.max(0, reach * reach - horizontal * horizontal));
    return ankle.y - 575 - vertical;
  }

  function resetPose() {
    cancelAnimationFrame(frameId);
    const rigPerson = document.getElementById('rig-person');
    if (rigPerson) {
      delete rigPerson.dataset.leftFootAngle;
      delete rigPerson.dataset.rightFootAngle;
      delete rigPerson.dataset.doubleSupport;
      delete rigPerson.dataset.swingPhase;
      delete rigPerson.dataset.flightPhase;
      delete rigPerson.dataset.gaitMode;
      delete rigPerson.dataset.leftLegPhase;
      delete rigPerson.dataset.rightLegPhase;
      delete rigPerson.dataset.runState;
      delete rigPerson.dataset.gaitStancePercent;
      delete rigPerson.dataset.gaitSwingPercent;
      delete rigPerson.dataset.workAmount;
      delete rigPerson.dataset.workPhase;
    }
    const workObject = document.getElementById('work-object');
    workObject?.setAttribute('visibility', 'hidden');
    workObject?.setAttribute('opacity', '0');
    document.getElementById('work-ground-foreground')?.setAttribute('visibility', 'hidden');
    document.getElementById('layer-work-head')?.setAttribute('visibility', 'hidden');
    document.getElementById('layer-ground')?.setAttribute('visibility', 'visible');
    document.documentElement.setAttribute('viewBox', '-80 0 880 1080');
    document.documentElement.setAttribute('width', '880');
    document.documentElement.setAttribute('height', '1080');
    document.getElementById('layer-back-arm')?.setAttribute('transform', 'translate(70 0)');
    document.querySelectorAll('.rig[data-pivot-x][data-pivot-y]').forEach(element => {
      if (element.id === 'rig-person') {
        element.setAttribute('transform', 'translate(0 0)');
      } else {
        const restAngle = Number(element.dataset.restAngle || 0);
        element.setAttribute('transform', `rotate(${restAngle} ${element.dataset.pivotX} ${element.dataset.pivotY})`);
      }
    });
    setLeftLegSpread(0);
  }

  function animate(now) {
    const seconds = Number.isFinite(fixedQaSeconds)
      ? Math.max(0, fixedQaSeconds)
      : (now - startedAt) / 1000;
    const mode = location.hash.slice(1);
    if (mode === 'wave') {
      const wave = Math.sin(seconds * 7);
      const settle = Math.sin(seconds * 3.5);
      rotate('rig-arm-right-upper', -62 + settle * 3);
      rotate('rig-arm-right-forearm', -112 + wave * 16);
      rotate('rig-hand-right', wave * 20);
      rotate('rig-arm-left-upper', -4 - settle * 2);
      rotate('rig-hand-left', settle * 5);
      rotate('rig-leg-left-upper', -settle * 0.5);
      rotate('rig-leg-right-upper', -settle * 0.5);
      rotate('rig-upper-body', -2 + settle * 1.5);
    } else if (mode === 'work' || mode.startsWith('work-')) {
      const poses = [
        { name: 'deep-squat', rootY: 190, torso: 55, frameX: -188, frameY: -298, scale: 1.14, leftUpper: -70, leftLower: 70, rightUpper: -76, rightLower: 76, leftArm: -40, leftElbow: -36, rightArm: -31, rightElbow: -30 },
        { name: 'one-knee', rootY: 220, torso: 52, frameX: 28, frameY: -34, scale: .87, leftUpper: -80, leftLower: 100, rightUpper: 0, rightLower: 90, leftArm: -39, leftElbow: -36, rightArm: -28, rightElbow: -30 }
      ];
      const requestedPose = mode === 'work' ? 'deep-squat' : mode.slice(5);
      const current = poses.find(pose => pose.name === requestedPose) || poses[0];
      const working = Math.sin(seconds * Math.PI * 2 * 1.5);

      setLeftLegSpread(0);
      document.getElementById('rig-person').setAttribute(
        'transform',
        `translate(${current.frameX} ${current.frameY}) scale(${current.scale}) translate(-80 ${current.rootY})`
      );
      document.documentElement.setAttribute('viewBox', '0 0 720 1040');
      document.documentElement.setAttribute('width', '720');
      document.documentElement.setAttribute('height', '1040');
      document.getElementById('layer-back-arm').setAttribute(
        'transform',
        `translate(70 0) rotate(${current.torso} 380 585)`
      );
      rotate('rig-leg-right-upper', current.rightUpper);
      rotate('rig-leg-right-lower', current.rightLower);
      rotate('rig-foot-right', 0);
      rotate('rig-leg-left-upper', current.leftUpper);
      rotate('rig-leg-left-lower', current.leftLower);
      rotate('rig-foot-left', 0);
      rotate('rig-arm-right-upper', current.rightArm - working * 1.2);
      rotate('rig-arm-right-forearm', current.rightElbow - working * 4);
      rotate('rig-hand-right', -working * 3);
      rotate('rig-arm-left-upper', current.leftArm + working * 1.2);
      rotate('rig-arm-left-forearm', current.leftElbow + working * 4);
      rotate('rig-hand-left', working * 3);
      rotate('rig-upper-body', current.torso);

      const rigPerson = document.getElementById('rig-person');
      rigPerson.dataset.gaitMode = `work-${current.name}`;
      rigPerson.dataset.workAmount = '1.000';
      rigPerson.dataset.workPhase = working.toFixed(3);
      rigPerson.dataset.workPose = current.name;
      const workObject = document.getElementById('work-object');
      workObject.setAttribute('visibility', 'visible');
      workObject.setAttribute('opacity', '1');
      document.getElementById('work-ground-foreground').setAttribute('visibility', 'visible');
      document.getElementById('layer-work-head').setAttribute('visibility', 'visible');
      document.getElementById('layer-ground').setAttribute('visibility', 'hidden');
    } else if (mode === 'walk') {
      const halfStepDuration = 0.68;
      const halfStepsPerLoop = 10;
      const stride = 250;
      const legOffset = 42;
      const loopTime = seconds % (halfStepDuration * halfStepsPerLoop);
      const halfStep = Math.floor(loopTime / halfStepDuration);
      const progress = (loopTime / halfStepDuration) - halfStep;
      const smoothstep = value => {
        const x = Math.max(0, Math.min(1, value));
        return x * x * (3 - 2 * x);
      };
      const easeRange = (start, end) => smoothstep((progress - start) / (end - start));
      const doubleSupportEnd = 0.18;
      const swingPhase = Math.max(0, Math.min(1,
        (progress - doubleSupportEnd) / (1 - doubleSupportEnd)
      ));
      const eased = smoothstep(swingPhase);
      const leftIsPlanted = halfStep % 2 === 0;
      const pair = Math.floor(halfStep / 2);
      const firstLeftContact = -137.5;
      const plantedContact = leftIsPlanted
        ? firstLeftContact + pair * stride * 2
        : firstLeftContact + pair * stride * 2 + stride - legOffset;
      const previousContact = leftIsPlanted
        ? plantedContact - stride - legOffset
        : plantedContact - stride + legOffset;
      const nextContact = leftIsPlanted
        ? plantedContact + stride - legOffset
        : plantedContact + stride + legOffset;
      const plantedHip = leftIsPlanted ? 392 : 392 - legOffset;
      const torsoLead = 26 * Math.sin(Math.PI * progress) ** 2;
      const rootX = plantedContact - (plantedHip + 50.5) + (progress - 0.5) * stride + torsoLead;
      const groundY = 1020;
      const plantedFootAngle = -8 * (1 - easeRange(0, 0.16))
        + 18 * easeRange(0.58, 1);
      const trailingToeOff = easeRange(0, doubleSupportEnd);
      const swingToeRecovery = easeRange(doubleSupportEnd, 0.50);
      const swingHeelPreparation = easeRange(0.85, 1);
      const swingingFootAngle = progress < doubleSupportEnd
        ? 18 + 8 * trailingToeOff
        : 24 * (1 - swingToeRecovery) - 8 * swingHeelPreparation;
      const leftHeelAngle = leftIsPlanted ? plantedFootAngle : swingingFootAngle;
      const rightHeelAngle = leftIsPlanted ? swingingFootAngle : plantedFootAngle;
      const rootY = plantedRootY(
        plantedContact,
        groundY,
        rootX,
        leftIsPlanted ? 0 : -legOffset,
        0,
        5
      ) - 2 * Math.sin(Math.PI * progress) ** 2;
      const swingingContact = previousContact + (nextContact - previousContact) * eased;
      const swingingY = groundY - 58 * Math.sin(Math.PI * swingPhase);
      const leftLeg = leftIsPlanted
        ? solveLeg(plantedContact, groundY, rootX, rootY, 0, leftHeelAngle)
        : solveLeg(swingingContact, swingingY, rootX, rootY, 0, leftHeelAngle);
      const rightLeg = leftIsPlanted
        ? solveLeg(swingingContact, swingingY, rootX, rootY, -legOffset, rightHeelAngle)
        : solveLeg(plantedContact, groundY, rootX, rootY, -legOffset, rightHeelAngle);

      // The planted shoe stays at one world-space point while the hip and knee pass over it.
      setLeftLegSpread(0);
      moveRoot(rootX, rootY);
      rotate('rig-leg-left-upper', leftLeg.upper);
      rotate('rig-leg-left-lower', leftLeg.lower);
      rotate('rig-foot-left', 0);
      rotate('rig-leg-right-upper', rightLeg.upper);
      rotate('rig-leg-right-lower', rightLeg.lower);
      rotate('rig-foot-right', 0);
      const armPhase = Math.cos(Math.PI * (halfStep + progress - 0.06));
      rotate('rig-arm-left-upper', armPhase * 12);
      rotate('rig-arm-right-upper', -armPhase * 12);
      rotate('rig-arm-left-forearm', -17 - Math.max(0, -armPhase) * 5);
      rotate('rig-arm-right-forearm', -12 - Math.max(0, armPhase) * 5);
      rotate('rig-upper-body', 0);
      const rigPerson = document.getElementById('rig-person');
      rigPerson.dataset.leftFootAngle = leftHeelAngle.toFixed(3);
      rigPerson.dataset.rightFootAngle = rightHeelAngle.toFixed(3);
      rigPerson.dataset.doubleSupport = String(progress < doubleSupportEnd);
      rigPerson.dataset.swingPhase = swingPhase.toFixed(3);
      rigPerson.dataset.gaitStancePercent = '62';
      rigPerson.dataset.gaitSwingPercent = '38';
      rigPerson.dataset.gaitMode = 'walk';
    } else if (mode === 'run') {
      const halfStepDuration = 0.40;
      const halfStepsPerLoop = 10;
      const stride = 410;
      const legOffset = 42;
      const dutyFactor = 0.20;
      const supportEnd = dutyFactor * 2;
      const loopTime = seconds % (halfStepDuration * halfStepsPerLoop);
      const halfStep = Math.floor(loopTime / halfStepDuration);
      const progress = (loopTime / halfStepDuration) - halfStep;
      const smoothstep = value => {
        const x = Math.max(0, Math.min(1, value));
        return x * x * x * (x * (x * 6 - 15) + 10);
      };
      const leftIsContactLeg = halfStep % 2 === 0;
      const pair = Math.floor(halfStep / 2);
      const firstLeftContact = -167.5;
      const contactLegContact = leftIsContactLeg
        ? firstLeftContact + pair * stride * 2
        : firstLeftContact + pair * stride * 2 + stride - legOffset;
      const otherPreviousContact = leftIsContactLeg
        ? contactLegContact - stride - legOffset
        : contactLegContact - stride + legOffset;
      const otherNextContact = leftIsContactLeg
        ? contactLegContact + stride - legOffset
        : contactLegContact + stride + legOffset;
      const contactHipShift = leftIsContactLeg ? 0 : -legOffset;
      const otherHipShift = leftIsContactLeg ? -legOffset : 0;
      const contactHip = 392 + contactHipShift;
      const rootX = contactLegContact - (contactHip + 50.5)
        + (progress - 0.13) * stride + 20;
      const groundY = 1020;

      const footState = (phase, previousContact, nextContact) => {
        if (phase < dutyFactor) {
          return { x: previousContact, y: groundY, stance: true };
        }
        const swingProgress = Math.max(0, Math.min(1,
          (phase - dutyFactor) / (1 - dutyFactor)
        ));
        const swingArc = Math.sin(Math.PI * swingProgress);
        return {
          x: previousContact + (nextContact - previousContact) * smoothstep(swingProgress),
          y: groundY - 155 * swingArc * swingArc,
          stance: false
        };
      };
      const footAngle = phase => {
        if (phase < dutyFactor) {
          const settle = smoothstep(phase / 0.08);
          const toeOff = smoothstep((phase - (dutyFactor - 0.16)) / 0.16);
          return -2 * (1 - settle) + 24 * toeOff;
        }
        const swingProgress = (phase - dutyFactor) / (1 - dutyFactor);
        const recovery = smoothstep(swingProgress / 0.28);
        const landingPreparation = smoothstep((swingProgress - 0.82) / 0.18);
        return 24 * (1 - recovery) - 2 * landingPreparation;
      };

      const contactLegPhase = progress * 0.5;
      const otherLegPhase = 0.5 + progress * 0.5;
      const contactFoot = footState(
        contactLegPhase,
        contactLegContact,
        contactLegContact + stride * 2
      );
      const otherFoot = footState(otherLegPhase, otherPreviousContact, otherNextContact);
      const contactFootAngle = footAngle(contactLegPhase);
      const otherFootAngle = footAngle(otherLegPhase);

      if (progress > supportEnd) {
        const flightProgress = (progress - supportEnd) / (1 - supportEnd);
        const flightArc = Math.sin(Math.PI * flightProgress);
        const sharedFlightLift = 65 * flightArc * flightArc;
        contactFoot.y -= sharedFlightLift;
        otherFoot.y -= sharedFlightLift;
      }

      const stanceProgress = Math.min(1, progress / supportEnd);
      let rootY = plantedRootY(
        contactLegContact,
        groundY,
        rootX,
        contactHipShift,
        contactFootAngle,
        11
      )
        - 2 * Math.sin(Math.PI * stanceProgress) ** 2;
      if (progress > supportEnd) {
        const flightProgress = (progress - supportEnd) / (1 - supportEnd);
        const takeoffRootX = contactLegContact - (contactHip + 50.5)
          + (supportEnd - 0.13) * stride + 20;
        const takeoffRootY = plantedRootY(
          contactLegContact,
          groundY,
          takeoffRootX,
          contactHipShift,
          footAngle(dutyFactor),
          11
        );
        const landingHip = 392 + otherHipShift;
        const landingRootX = otherNextContact - (landingHip + 50.5) - stride * 0.13 + 20;
        const landingRootY = plantedRootY(
          otherNextContact,
          groundY,
          landingRootX,
          otherHipShift,
          footAngle(0),
          11
        );
        const flightArc = Math.sin(Math.PI * flightProgress);
        rootY = takeoffRootY
          + (landingRootY - takeoffRootY) * smoothstep(flightProgress)
          - 30 * flightArc * flightArc;
      }

      const leftFoot = leftIsContactLeg ? contactFoot : otherFoot;
      const rightFoot = leftIsContactLeg ? otherFoot : contactFoot;
      const leftHeelAngle = leftIsContactLeg ? contactFootAngle : otherFootAngle;
      const rightHeelAngle = leftIsContactLeg ? otherFootAngle : contactFootAngle;
      const leftLeg = solveLeg(leftFoot.x, leftFoot.y, rootX, rootY, 0, leftHeelAngle);
      const rightLeg = solveLeg(rightFoot.x, rightFoot.y, rootX, rootY, -legOffset, rightHeelAngle);

      setLeftLegSpread(0);
      moveRoot(rootX, rootY);
      rotate('rig-leg-left-upper', leftLeg.upper);
      rotate('rig-leg-left-lower', leftLeg.lower);
      rotate('rig-foot-left', 0);
      rotate('rig-leg-right-upper', rightLeg.upper);
      rotate('rig-leg-right-lower', rightLeg.lower);
      rotate('rig-foot-right', 0);
      const armPhase = Math.cos(Math.PI * (halfStep + progress));
      rotate('rig-arm-left-upper', armPhase * 32);
      rotate('rig-arm-right-upper', -armPhase * 32);
      rotate('rig-arm-left-forearm', -42 - Math.max(0, -armPhase) * 12);
      rotate('rig-arm-right-forearm', -40 - Math.max(0, armPhase) * 12);
      document.getElementById('rig-upper-body').setAttribute(
        'transform',
        'rotate(14 380 585)'
      );

      const rigPerson = document.getElementById('rig-person');
      rigPerson.dataset.leftFootAngle = leftHeelAngle.toFixed(3);
      rigPerson.dataset.rightFootAngle = rightHeelAngle.toFixed(3);
      rigPerson.dataset.doubleSupport = 'false';
      rigPerson.dataset.flightPhase = String(progress > supportEnd);
      rigPerson.dataset.leftLegPhase = (leftIsContactLeg ? contactLegPhase : otherLegPhase).toFixed(3);
      rigPerson.dataset.rightLegPhase = (leftIsContactLeg ? otherLegPhase : contactLegPhase).toFixed(3);
      rigPerson.dataset.gaitStancePercent = '20';
      rigPerson.dataset.gaitSwingPercent = '80';
      rigPerson.dataset.gaitMode = 'run';
      rigPerson.dataset.runState = JSON.stringify({
        halfStep,
        progress: Number(progress.toFixed(4)),
        flight: progress > supportEnd,
        contact: progress > supportEnd ? 'none' : (leftIsContactLeg ? 'left' : 'right'),
        rootY: Number(rootY.toFixed(3)),
        leftFootY: Number(leftFoot.y.toFixed(3)),
        rightFootY: Number(rightFoot.y.toFixed(3)),
        leftArm: Number((armPhase * 32).toFixed(3)),
        rightArm: Number((-armPhase * 32).toFixed(3))
      });
    } else {
      return;
    }
    if (!Number.isFinite(fixedQaSeconds)) {
      frameId = requestAnimationFrame(animate);
    }
  }

  function startMode() {
    resetPose();
    const mode = location.hash.slice(1);
    if (mode !== 'wave' && mode !== 'walk' && mode !== 'run' && mode !== 'work' && !mode.startsWith('work-')) return;
    startedAt = performance.now();
    frameId = requestAnimationFrame(animate);
  }

  window.addEventListener('hashchange', startMode);
  startMode();
})();
